          <div className="flex items-center gap-6">
            <button className="relative p-2 text-slate-400 hover:text-indigo-600 transition-colors">
              <Bell className="w-5 h-5" />
              <span className="absolute top-2 right-2 w-2 h-2 bg-rose-500 rounded-full border-2 border-white"></span>
            </button>

            <div className="relative">
              <button 
                onClick={() => setIsProfileOpen(!isProfileOpen)}
                className="flex items-center gap-3 p-1.5 pl-3 rounded-2xl hover:bg-slate-50 transition-all border border-transparent hover:border-slate-100"
              >
                <div className="text-right hidden sm:block">
                  <p className="text-xs font-black text-slate-800 truncate max-w-[120px]">{currentUser?.name}</p>
                  <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-tighter">{currentUser?.church_id}</p>
                </div>
                <div className="w-10 h-10 rounded-xl bg-indigo-100 flex items-center justify-center text-indigo-600 font-black shadow-inner">
                  {currentUser?.name?.[0]}
                </div>
                <ChevronDown className={`w-4 h-4 text-slate-400 transition-transform ${isProfileOpen ? 'rotate-180' : ''}`} />
              </button>

              {isProfileOpen && (
                <div className="absolute right-0 mt-3 w-56 bg-white rounded-3xl shadow-2xl shadow-indigo-100 border border-slate-100 py-3 z-50 animate-in fade-in zoom-in-95 duration-200">
                  <div className="px-5 py-3 border-b border-slate-50 mb-2">
                    <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Minha Conta</p>
                  </div>
                  <button className="w-full flex items-center gap-3 px-5 py-3 text-sm font-bold text-slate-700 hover:bg-slate-50 hover:text-indigo-600 transition-all">
                    <User className="w-4 h-4" /> Perfil
                  </button>
                  <button className="w-full flex items-center gap-3 px-5 py-3 text-sm font-bold text-slate-700 hover:bg-slate-50 hover:text-indigo-600 transition-all">
                    <Settings className="w-4 h-4" /> Configurações
                  </button>
                  <div className="h-px bg-slate-50 my-2"></div>
                  <button 
                    onClick={handleLogout}
                    className="w-full flex items-center gap-3 px-5 py-3 text-sm font-bold text-rose-500 hover:bg-rose-50 transition-all"
                  >
                    <LogOut className="w-4 h-4" /> Sair do Sistema
                  </button>
                </div>
              )}
            </div>
          </div>
        </header>

        {/* Dynamic View */}
        <div className="flex-1 overflow-hidden relative">
          {activeTab === 'analytics' && <AnalyticsDashboard members={members} />}
          {activeTab === 'kanban' && (
            <KanbanBoard 
              members={members} 
              events={events} 
              onMoveMember={moveMember} 
              onAddMember={() => setActiveTab('kanban')} 
            />
          )}
          {activeTab === 'agenda' && (
            <ScheduleModule 
              events={events} 
              onAddEvent={(date) => console.log('Add event at', date)} 
              onEditEvent={(ev) => console.log('Edit', ev)}
            />
          )}
          {activeTab === 'automation' && <AutomationSettings />}
          {activeTab === 'settings' && (
            <div className="p-10 flex flex-col items-center justify-center h-full text-slate-400 gap-4">
              <Settings className="w-16 h-16 animate-pulse text-slate-300" />
              <p className="font-bold text-sm uppercase tracking-widest text-slate-500">Módulo de configurações em expansão</p>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;
